def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        cells = [c for c, v in enumerate(row) if v != bg]
        if cells:
            end = max(cells)
            if end < len(row)-1:
                for c in range(end+1, len(row)):
                    out[r][c] = 1
    return out
